const payload = $input.first().json.body;
const runId = payload.resource?.id || payload.eventData?.actorRunId;

if (!runId) {
  throw new Error('No runId: ' + JSON.stringify(payload));
}

return [{ json: { runId } }];

const items = $input.all();
const jobs = items.map(i => i.json).flat();
if (!Array.isArray(jobs) || jobs.length === 0) return [];

const seen = new Set();

return jobs
  .filter(j => j.jobTitle && j.jobDescription && j.jobDescription.length > 100)
  .map(j => ({
    title: j.jobTitle,
    company: j.companyName || 'Unknown',
    location: j.location || 'Israel',
    description: (j.jobDescription || '').substring(0, 2000),
    jobUrl: j.jobUrl || j.applyUrl || '',
    applicantsCount: j.applicationsCount || 'Unknown',
    postedAt: j.postedTime || j.publishedAt || '',
    contractType: j.contractType || '',
    experienceLevel: j.experienceLevel || ''
  }))
  .filter(j => {
    const key = j.jobUrl || (j.title + '|' + j.company);
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  })
  .map(j => ({ json: j }));

const item = $input.item.json;

let text = '';
if (item.content && Array.isArray(item.content)) {
  text = item.content[0]?.text || '';
} else if (item.text) {
  text = item.text;
} else {
  text = JSON.stringify(item);
}

const clean = text.replace(/```json\s*/g, '').replace(/```\s*/g, '').trim();
const jsonMatch = clean.match(/\{[\s\S]*\}/);
const jsonStr = jsonMatch ? jsonMatch[0] : clean;

let analysis;
try {
  analysis = JSON.parse(jsonStr);
} catch(e) {
  analysis = { score: 0, parseError: true, rawText: text };
}

// נסה לשלוף jobUrl מהפרומפט שנשלח
const promptText = item.messages?.[0]?.content || '';
const urlMatch = promptText.match(/JobUrl:\s*(https?:\/\/[^\s\n]+)/);
const jobUrl = urlMatch?.[1] || analysis.jobUrl || '';

return { json: { 
  ...analysis,
  score: Number(analysis.score) || 0,
  jobUrl: jobUrl
}};

const allItems = $input.all();
const aggregated = allItems[0]?.json;

let jobs = [];
if (aggregated?.jobs && Array.isArray(aggregated.jobs)) {
  jobs = aggregated.jobs;
} else {
  jobs = allItems.map(i => i.json);
}

jobs = jobs
  .filter(j => j && !j.parseError)
  .map(j => ({ ...j, score: Number(j.score) || 0 }))
  .filter(j => j.score > 0)
  .sort((a, b) => b.score - a.score);

if (jobs.length === 0) {
  return [{ json: { html: '<p style="font-family:Arial;direction:rtl">אין משרות מתאימות היום.</p>', count: 0 } }];
}

const rows = jobs.map(j => {
  const color = j.score >= 65 ? '#27500A' : '#633806';
  const bg    = j.score >= 65 ? '#EAF3DE' : '#FAEEDA';
  const letter = (j.cover_letter || j.cover_letter_he || '').replace(/\n/g, '<br>');
  const improveCv     = (j.improve_cv     || []).map(x => `<li>${x}</li>`).join('');
  const improveSkills = (j.improve_skills || []).map(x => `<li>${x}</li>`).join('');

  return `
  <tr style="border-bottom:1px solid #ddd">
    <td style="padding:10px;font-weight:500">${j.title || ''}</td>
    <td style="padding:10px;color:#555">${j.company || ''}</td>
    <td style="padding:10px;color:#666">${j.location || ''}</td>
    <td style="padding:10px;text-align:center">
      <span style="background:${bg};color:${color};padding:3px 8px;border-radius:12px;font-weight:500">${j.score}</span>
    </td>
    <td style="padding:10px">${j.probability || '-'}</td>
    <td style="padding:10px">
      <a href="${j.jobUrl || '#'}" style="background:#1D9E75;color:white;padding:4px 10px;border-radius:6px;text-decoration:none">הגש</a>
    </td>
  </tr>
  <tr style="background:#f5f5f5">
    <td colspan="6" style="padding:8px 10px;font-size:12px">
      <strong style="color:#3B6D11">✓ חוזקות:</strong> ${(j.strengths||[]).join(' · ')}<br>
      <strong style="color:#A32D2D">✗ פערים:</strong> ${(j.gaps||[]).join(' · ')}
    </td>
  </tr>
  <tr style="background:#fafff8">
    <td colspan="6" style="padding:8px 10px;font-size:12px">
      <strong style="color:#185FA5">✎ שיפורי קו"ח:</strong>
      <ul style="margin:4px 0 8px 20px;padding:0">${improveCv}</ul>
      <strong style="color:#185FA5">📚 קורסים מומלצים:</strong>
      <ul style="margin:4px 0 4px 20px;padding:0">${improveSkills}</ul>
    </td>
  </tr>
  <tr style="border-bottom:3px solid #ccc">
    <td colspan="6" style="padding:8px 10px;font-size:13px;direction:ltr;line-height:1.7">
      <strong>Cover letter:</strong><br>${letter}
    </td>
  </tr>`;
}).join('');

const today = new Date().toLocaleDateString('he-IL');
const html = `<div style="font-family:Arial,sans-serif;max-width:800px;margin:auto;direction:rtl">
  <h2 style="color:#1D9E75;border-bottom:2px solid #1D9E75;padding-bottom:8px">משרות חדשות לצביקה — ${today}</h2>
  <p>נמצאו <strong style="color:#1D9E75">${jobs.length}</strong> משרות עם ציון 55+</p>
  <table style="width:100%;border-collapse:collapse">
    <thead><tr style="background:#f0f0f0">
      <th style="padding:10px;text-align:right">תפקיד</th>
      <th style="padding:10px;text-align:right">חברה</th>
      <th style="padding:10px;text-align:right">מיקום</th>
      <th style="padding:10px">ציון</th>
      <th style="padding:10px">סיכוי</th>
      <th style="padding:10px">קישור</th>
    </tr></thead>
    <tbody>${rows}</tbody>
  </table>
</div>`;

return [{ json: { html, count: jobs.length } }];

